for x in ['persons','doors','packets','trains','bytes','cases','bits','states','axles',
          'percent','ppm','points','microstrain','rad','mrad','cycles','independent trials',
          'failure probability','alarms','dB']:
 U[x]=Z

def dimensions(node,symbols):
 if isinstance(node,ast.Expression): return dimensions(node.body,symbols)
 if isinstance(node,ast.Constant): return Z
 if isinstance(node,ast.Name): return symbols.get(node.id,Z)
 if isinstance(node,ast.UnaryOp): return dimensions(node.operand,symbols)
 if isinstance(node,ast.BinOp):
  a,b=dimensions(node.left,symbols),dimensions(node.right,symbols)
  if isinstance(node.op,(ast.Add,ast.Sub)):
   assert a==b,(ast.unparse(node),a,b)
   return a
  if isinstance(node.op,ast.Mult):return tuple(x+y for x,y in zip(a,b))
  if isinstance(node.op,ast.Div):return tuple(x-y for x,y in zip(a,b))
  if isinstance(node.op,ast.Pow):
   assert b==Z
   if a==Z:return Z
   assert isinstance(node.right,ast.Constant)
   return tuple(x*node.right.value for x in a)
 if isinstance(node,ast.Call):
  d=dimensions(node.args[0],symbols)
  if node.func.id=='sqrt':return tuple(x/2 for x in d)
  assert node.func.id=='log10' and d==Z
  return Z
 raise ValueError(ast.dump(node))

cases=[]
for key,m in MODELS.items():
 if key not in REF:continue # Newly cloned context model receives separate final-input review.
 symbols={q[0]:U[q[2]] for q in m['quantities']}
 derived=dimensions(ast.parse(m['expression'],mode='eval'),symbols)
 assert derived==U[m['result_unit']],(key,derived,U[m['result_unit']])
 values={q[0]:q[1] for q in m['quantities']}
 result=eval(compile(ast.parse(m['expression'],mode='eval'),'<reviewed expression>','eval'),
             {'__builtins__':{},'sqrt':math.sqrt,'log10':math.log10,'pi':math.pi},values)
 assert math.isclose(result,REF[key],rel_tol=1e-10,abs_tol=1e-10),(key,result,REF[key])
 cases.append({'model':key,'expected':REF[key],'actual':result,'unit':m['result_unit'],
               'dimensionCheck':'PASS','numericCheck':'PASS','boundaryReviewed':True})

out=ROOT/'tools/rail-v16/reviews/peer_control.json'
previous=json.loads(out.read_text()) if out.exists() else {}
previous.update({'reviewer':'v16_scene (independent of control author)',
 'date':'2026-10-23','status':'NUMERICS_PASS',
 'modelSourceSha256':hashlib.sha256(SOURCE.read_bytes()).hexdigest(),
 'method':'Independent reduced reference values plus AST-based SI dimensional analysis; manual reading of mechanism/boundary/verification text. Reviewer authored course briefs b391–b400; those briefs require review by another author.',
 'modelCountReviewed':len(cases),'cases':cases,
 'limits':['No operational safety certification is inferred.','Course briefs b391–b400 were authored by this reviewer and require a different reviewer.','This report does not claim independent retrieval of every supplemental product page.']})
checks_file=ROOT/'tools/rail-v16/authored_control/numeric_checks.json'
if checks_file.exists():
 generated=json.loads(checks_file.read_text())
 count_units={'bits','cases','trains','persons','points','cycles','alarms','axles','packets','independent trials'}
 for item in generated:
  s=item['sensitivity']
  values={q[0]:q[1] for q in item['quantities']}
  values[s['symbol']]=s['changed']
  actual=eval(compile(ast.parse(item['expression'],mode='eval'),'<generated scenario>','eval'),
              {'__builtins__':{},'sqrt':math.sqrt,'log10':math.log10,'pi':math.pi},values)
  assert math.isfinite(actual) and math.isclose(actual,s['result'],rel_tol=1e-10,abs_tol=1e-10),item
  if s['inputUnit'] in count_units:
   assert s['changed']==int(s['changed']) and s['changed']==s['base']+1,item
  if item['model']=='coverage':assert 0<=s['result']<=1,item
 previous['generatedScenarioChecks']={'status':'PASS','cases':len(generated),
  'courses':len(set(x['course'] for x in generated)),
  'sha256':hashlib.sha256(checks_file.read_bytes()).hexdigest(),
  'checks':['Every result finite and recomputed using its changed parameter.',
            'Discrete quantities increase by one whole count; no fractional bits, axles, persons, cases or alarms.',
            'Coverage sensitivities remain within zero and one.']}
out.write_text(json.dumps(previous,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'status':'PASS','modelCount':len(cases),'report':str(out)}))
